def solve(g):
    H,W=len(g),len(g[0])
    bg=max(set(x for r in g for x in r),key=lambda v:sum(r.count(v) for r in g))
    # bands
    bs=[]; start=None
    for r in range(H):
        if any(x!=bg for x in g[r]):
            if start is None: start=r
        else:
            if start is not None: bs.append((start,r-1)); start=None
    if start is not None: bs.append((start,H-1))
    b=[row[:] for row in g]
    ext=True
    while ext:
        ext=False
        for i,(s,e) in enumerate(bs):
            for j,(s2,e2) in enumerate(bs):
                if i==j or s>e2+1: continue
                h=min(e-s,e2-s2)
                for dr in range(h):
                    r1,r2=s+dr,s2+dr
                    for cc in range(W):
                        if g[r1][cc]==bg and g[r2][cc]!=bg:
                            b[r1][cc]=1; ext=True; break
    return b
